// Settings clamps (R2). `showChannelName` is `!== false`; strings are trimmed.
var SETTING_RANGES = {
  refreshMinutes: { def: 360, min: 15, max: 1440 },
  maxRecents: { def: 10, min: 1, max: 50 },
  barLabelMaxWidth: { def: 180, min: 60, max: 600 },
  // M2-03 CN2: the inter-digit window is a setting, not a constant, because
  // the gap between a slow typist getting channel 101 and getting channels
  // 1, 0 and 1 is an accessibility matter.
  numberEntryMs: { def: 2000, min: 400, max: 5000 },
  // M2-05 section 6. The box is a PERCENTAGE of the monitor, not a pixel
  // constant (PIP4): Omarchy's own 600x338 would take 44 percent of this
  // 1366x768 display in both axes, and omarchy-hyprland-window-pop's
  // 1300x900 is taller than the screen.
  pipSizePercent: { def: 30, min: 15, max: 60 },
  pipMargin: { def: 16, min: 0, max: 200 }
}

// Channel numbers (M2-03 1.2 / 9.1). A number is at most 5 major digits and
// an optional 1-to-3 digit subchannel. MAX_CHNO_LABEL is the hard bound the
// row column's width formula is derived from (4.2) and the entry buffer's
// cap (2.4).
//
// It is 9, not the 7 of design 1.2 step 9. That step calls a 7-character
// label "unreachable given 4 and 6", which is wrong: the grammar it states
// two steps earlier admits "99999.999", which is nine. At 7 the parser would
// have had to reject a number its own grammar allows, and the buffer cap
// would have made a displayed channel untypable -- the exact failure CN6
// rejects for non-numeric values. The grammar is authoritative; the derived
// bound follows it. See the lane A report, request 2.
var MAX_CHNO_MAJOR = 99999
var MAX_CHNO_MINOR = 999
var MAX_CHNO_LABEL = 9
// CN8: providers write both "7.1" and "8-1", so both are accepted on PARSE;
// only "." is ever produced, and it is what the user types (plus ",", which
// is what the numpad decimal key emits on several layouts -- see the Gate A1
// evidence in the M2-03 lane A report).
var CHNO_SEPARATORS = ".-"
var CHNO_ENTRY_SEP = "."
var CHANNEL_ORDERS = ["playlist", "number"]
// CN11: the product owner's amendment to OQ 11. `tvg-chno` is what every
// asset uses, but a playlist that silently has no numbers is the worst
// failure this feature can have, so the aliases are read too. The helper's
// record whitelist decides which of these can actually arrive (see the lane
// A report, request 1); the model reads whichever is present.
var CHNO_FIELDS = ["chno", "tvgChno", "channelNumber", "tvg-chno", "tvg-channel-number", "channel-number"]

// mpv options the user may not override through the mpvArgs setting because
// the service depends on them (socket, window identity, exit semantics).
// The ten additions below (ARCHITECTURE-PLAYER.md 4.12) are not invariants of
// the service: each one writes the credentialed stream URL somewhere durable
// or on screen, which is the very exposure M2-02 closes (S-03). `--ytdl` is
// deliberately NOT reserved (PO-5): re-enabling yt-dlp is the documented
// escape hatch for non-direct URLs.
var MPV_RESERVED = {
  "--input-ipc-server": true,
  "--wayland-app-id": true,
  "--title": true,
  "--force-media-title": true,
  "--idle": true,
  "--input-ipc-client": true,
  // D-SINK-2. `--script` is not the option: mpv's own `--list-options` calls it
  // "alias for --scripts-append". So reserving it and not `--scripts-append`
  // reserved the alias and left the real option open, and a pasted
  // `--scripts-append=/tmp/x.lua` ran arbitrary Lua inside the player, which
  // can read `path` -- the credentialed stream URL. The reserved set is now
  // matched against the option's BASE name (mpvOptionBase strips -append,
  // -add, -set, -pre, -clr, -del, -remove, -toggle), so every spelling of a
  // list option is covered by naming it once.
  "--script": true,
  "--scripts": true,
  // D-SINK-4. Reserved, not merely defaulted off, and the distinction is the
  // whole fix. `--load-scripts=no` is in the base argv, but user mpvArgs are
  // concatenated AFTER it (buildMpvArgv's tail, which since D-SINK-13 only
  // the trailing TLS re-assertion follows), so a pasted
  // `--load-scripts=yes` would win and silently put the credentialed stream
  // URL back on the session bus. That is the shape of D-SINK-2 again: an
  // option defaulted rather than reserved is an option the user can undo
  // without knowing what it was for.
  //
  // Unlike `--ytdl`, which is deliberately left re-enablable (PO-5) because
  // it trades speed for reach, this one guards a credential and has no
  // legitimate counter-position.
  "--load-scripts": true,
  // NOT --script-opts: ruling PO-10 / D-PLY-5 keeps it a HANDOFF option,
  // allowed with a warning, and the suite holds that line. Base-name matching
  // still covers its spellings, so --script-opts-append warns like --script-opts
  // rather than slipping through unwarned.
  "--include": true,              // loads a config file, which can set any of these
  "--config-dir": true,
  "--log-file": true,             // 0644, forced -v -v, writes the URL per failed load
  "--dump-stats": true,           // on-disk file carrying the command line
  "--stream-record": true,        // writes the stream itself to disk
  "--save-position-on-quit": true, // watch-later file whose header is the stream path
  "--watch-later-dir": true,
  "--osd-msg1": true,             // property-expanding: ${path} on screen and in screenshots
  "--osd-msg2": true,
  "--osd-msg3": true,
  "--term-status-msg": true,      // property-expanding into a terminal
  "--screenshot-template": true,  // property-expanding into file names
  // M5-01 (design 2.6, D3). Not whether mpv caches on disk but whether the
  // file OUTLIVES the process: mpv unlinks its cache file at creation
  // (F-RWD-5), and `whendone` or `no` here keeps a copy of the stream at a
  // path the plugin never listed -- `--stream-record`'s class, reserved
  // above. `--cache-on-disk` itself is the user's own disk and is warned
  // about (MPV_DISK_WARN), not refused.
  "--demuxer-cache-unlink-files": true,
  // D-SINK-13, layer 3 of four. mpv's `--tls-verify` defaults to NO, so until
  // this round the plugin handed provider headers and an HTTPS stream URL to
  // an UNAUTHENTICATED peer: measured by the lead on 2026-10-07 against a
  // self-signed server, the shipped argv played it, exit 0. The TLS peer is a
  // sink like any other on the rule 5 list, and it is the one sink that gets
  // the credential in full rather than redacted.
  //
  // Reserved here, and ALSO re-asserted as the final token of the composed
  // argv (buildMpvArgv). The two are not alternatives and the brief for each
  // is different: the trailing token is what makes verification SAFE, because
  // a later command-line token beats an earlier one and `--profile` carries
  // arbitrary options; this entry is what makes the refusal HONEST, so a user
  // who writes `--tls-verify=no` is told it was dropped instead of watching it
  // be silently undone. Both spellings are covered without a new branch: the
  // `--no-` arm below reconstructs `--tls-verify` from `--no-tls-verify` and
  // finds it here.
  //
  // NOT reserved, on purpose, and both of them matter:
  //  - `--tls-ca-file` is the targeted escape for a provider presenting a
  //    self-signed or private-CA certificate. The lead measured it working
  //    behind the trailing re-assertion (case C, and again in the addendum).
  //    It is the `--screenshot-dir` shape: a deliberate user choice that lands
  //    after our token and still wins. The cost of the ruling, stated rather
  //    than hidden: such a user can no longer disable verification wholesale,
  //    they must name that provider's CA. Smaller blast radius, same
  //    capability.
  //  - `--profile` is a legitimate mpv feature, and reserving it would cost
  //    users that feature while still leaving whatever indirection nobody has
  //    thought of yet. The trailing re-assertion is what makes it harmless, so
  //    this is the list NOT to reach for when someone remembers the profile
  //    bypass.
  // `--tls-cert-file` and `--tls-key-file` are CLIENT certificates, a
  // different thing, and are untouched.
  // D-SINK-13, and the reason layer 2 is not the whole fix. `--stream-lavf-o`
  // hands key=value straight to libavformat for the STREAM, and FFmpeg's own
  // AVOption is `tls_verify` -- a different knob from mpv's `--tls-verify`,
  // reaching the same place. So the trailing re-assertion cannot outvote it:
  // measured by the lead on 2026-10-07 against the self-signed server, with
  // BOTH tls-verify tokens in place, `--stream-lavf-o=tls_verify=0` PLAYED the
  // attacker's stream (exit 0), and so did the `-add`, `-append` and `-set`
  // forms, with the GET in the attacker's log each time. Found by all three
  // reviewers of this round independently, against the four-layer fix.
  //
  // This one can ONLY be closed by the reserved list, which is why the list is
  // load-bearing again here and why "layer 2 covers the indirections nobody has
  // enumerated" was too strong a sentence. mpvOptionBase strips the list
  // suffixes, so this single entry covers all six spellings.
  //
  // `--demuxer-lavf-o` is NOT reserved: measured on the same server, it does
  // NOT bypass verification (exit 2, refused), because it configures the
  // demuxer rather than the protocol. Recorded as measured rather than
  // reserved on suspicion.
  "--stream-lavf-o": true,
  "--tls-verify": true
}

// D-SINK-13, layers 1 and 2. ONE string, written into the argv TWICE on
// purpose. See buildMpvArgv for why the second occurrence is load-bearing;
// the constant exists so the two can never drift apart, the way PIP_CLASS
// exists. The python mirror keeps its own literal and the two are pinned to
// each other by the shared player-argv.json vectors.
var MPV_TLS_VERIFY = "--tls-verify=yes"

// D-SINK-16. The same two knobs as D-SINK-13, named as mpv PROPERTIES rather
// than as command-line options, because an ADOPTED player has no launch argv
// left to change. All four of D-SINK-13's layers live on the argv, so a
// process started by 0.12.1 - mpv's own default is `tls-verify=no` - goes on
// not verifying after the upgrade, and the helper goes on sending it new
// provider headers and a new credentialed URL on every zap. Mirrored by
// MPV_TLS_VERIFY_PROP / MPV_STREAM_OPTS_PROP in the helper.
var MPV_TLS_VERIFY_PROP = "tls-verify"
var MPV_STREAM_OPTS_PROP = "stream-lavf-o"

// Stable notification replace-ids so a repeated failure replaces its toast
// instead of stacking (UX.md 6.4).
var NOTIFY_IDS = {
  streamFailed: 74011,
  playlistRefreshed: 74012,
  playlistError: 74013,
  epgError: 74014,
  mpvMissing: 74015,
  // D-SINK-19 round 11, R21b: a URL taken off the bar entry unadopted. One id
  // for every such report, so a second replaces the first on screen rather
  // than stacking (a user who sets both URLs sees one card, the last).
  entryInputRefused: 74016,
  // D-SINK-19 round 12, R22a: state.json did not load and nothing will be
  // written this session (Model.stateUnreadableNotice). Told once per episode.
  stateUnreadable: 74017,
  // D-SINK-19 round 15, R25b: a merge of another program's write dropped an
  // in-app addition at a cap (Model.mergeDropNotice). Told once per merge.
  mergeDropped: 74018
  // 74019 was R28a's "Saving is waiting" card, withdrawn by R29a with the
  // held save it told about; not reused, so an old card cannot be replaced
  // by a new meaning.
}

// Long enough to cover a first-load failure and the user's reaction, short
// enough that it is never a surprise.
var PLACE_TTL_SEC = 180

var ZAP_MAX_SKIP = 20
export {
  MAX_ROWS_DEFAULT, MAX_CHANNELS, STOP_QUIT_GRACE_MS, STOP_KILL_GRACE_MS,
  HEALTH_SKIPS_BEFORE_RESTART, PLAYER_STASH_SCHEMA, PLAYER_ORPHAN_GRACE_SEC,
  PLAYER_GENERIC_FAILURE, PLAYER_LOG_TAIL, PLAYER_ENTRY_OWNERS,
  FAVORITES_GROUP, RECENT_GROUP, UNGROUPED, STATE_VERSION, PLUGIN_VERSION,
  manifestVersion, staleBuild, SCOPE_RECENT, SCOPE_FAVORITES, SCOPE_ALL,
  GROUP_SCOPE_PREFIX, MAX_HIDDEN_GROUPS, ELLIPSIS, QUOTE_OPEN, QUOTE_CLOSE,
  SEP, GLYPHS, SETTING_RANGES, MAX_CHNO_MAJOR, MAX_CHNO_MINOR, MAX_CHNO_LABEL,
  CHNO_SEPARATORS, CHNO_ENTRY_SEP, CHANNEL_ORDERS, CHNO_FIELDS, MPV_RESERVED,
  MPV_TLS_VERIFY, MPV_TLS_VERIFY_PROP, MPV_STREAM_OPTS_PROP, NOTIFY_IDS,
  PLACE_TTL_SEC, ZAP_MAX_SKIP
}
